; Generated by tools/nes_sfx2smps.py from smb1-disasm-master (SMB1 VictoryMusic) - do not edit by hand.
; One 384-frame pass at one tick per frame (tempo $FF), looping back to the start
; where SMB1's EndOfMusicData restarts it (VictoryMLoopBack). The S2 driver skips one
; tick every 256 frames, so it runs 0.39% slower than SMB1. Stored uncompressed.
; The squares are PSG1/2 (SMB1 plays them at 50% duty, the PSG's own wave); the
; triangle is FM1 with a triangle-like voice (harmonics 1/3/5/7), volume $1C.
MarioVictory_Header:
	smpsHeaderStartSong 2
	smpsHeaderVoice     MarioVictory_Voices
	smpsHeaderChan      $02, $02
	smpsHeaderTempo     $01, $FF

	smpsHeaderDAC       MarioVictory_DAC
	smpsHeaderFM        MarioVictory_FM1,	$00, $1C
	smpsHeaderPSG       MarioVictory_PSG1,	$00, $05, $00, $00
